<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Mail;
use ZipArchive;
class DatabaseBackup extends Command { protected $signature='judibas:backup {--force}'; protected $description='Create and email the configured PostgreSQL backup';
 public function handle():int { $s=DB::table('platform_backup_settings')->first();if(!$s||(!$s->enabled&&!$this->option('force')))return 0;$dir=storage_path('app/private/backups');if(!is_dir($dir))mkdir($dir,0700,true);$stamp=now()->format('Y-m-d_H-i-s');$dump=$dir.'/judibas_'.$stamp.'.dump';$zip=$dir.'/judibas_'.$stamp.'.zip';$db=config('database.connections.pgsql');$cmd=[$this->binary('pg_dump'),'--format=custom','--no-owner','--file='.$dump,'--host='.($db['host']??'127.0.0.1'),'--port='.($db['port']??5432),'--username='.($db['username']??''),$db['database']??''];$env=['PGPASSWORD'=>$db['password']??''];$process=new \Symfony\Component\Process\Process($cmd,null,$env);$process->setTimeout(600);try{$process->mustRun();$z=new ZipArchive;if($z->open($zip,ZipArchive::CREATE)!==true)throw new \RuntimeException('Unable to create ZIP archive.');$z->addFile($dump,basename($dump));$z->close();unlink($dump);$recipients=array_filter(array_map('trim',preg_split('/[,;\s]+/',$s->recipients)));if(!$recipients)throw new \RuntimeException('No backup recipient configured.');Mail::raw('Your Judibas database backup is attached. Keep it in a secure location.',function($m)use($recipients,$zip,$stamp){$m->to($recipients)->subject('Judibas database backup '.$stamp)->attach($zip,['as'=>'judibas-backup-'.$stamp.'.zip','mime'=>'application/zip']);});$this->cleanup($dir,(int)$s->retention);DB::table('platform_backup_settings')->update(['last_run_at'=>now(),'last_status'=>'success','last_error'=>null,'updated_at'=>now()]);$this->info('Backup created and emailed.');return 0;}catch(\Throwable $e){if(file_exists($dump))unlink($dump);if(file_exists($zip))unlink($zip);DB::table('platform_backup_settings')->update(['last_run_at'=>now(),'last_status'=>'failed','last_error'=>substr($e->getMessage(),0,1000),'updated_at'=>now()]);$this->error($e->getMessage());return 1;} }
 private function binary(string $name):string{return PHP_OS_FAMILY==='Windows'?$name.'.exe':$name;}
 private function cleanup(string $dir,int $keep):void{$files=glob($dir.'/judibas_*.zip')?:[];usort($files,fn($a,$b)=>filemtime($b)<=>filemtime($a));foreach(array_slice($files,max(1,$keep)) as $file)@unlink($file);}
}
